```c
#include <stdio.h>

#define MAX_SUM 1000000

static int freq[MAX_SUM + 1];

int main(void) {
    int n, s;
    if (scanf("%d", &n) != 1) return 0;
    if (scanf("%d", &s) != 1) return 0;

    freq[0] = 1;
    int sum = 0;
    long long ans = 0;

    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        sum += x;
        if (sum >= s) {
            ans += freq[sum - s];
        }
        freq[sum]++;
    }

    printf("%lld\n", ans);
    return 0;
}
```

